(()=>{
  const img=document.querySelector('[data-map-image]');
  // find which CSS rules apply to img with transform
  const out=[];
  for(const sheet of document.styleSheets){
    let rules; try{rules=sheet.cssRules}catch(e){continue}
    for(const r of rules){
      if(r.selectorText && r.style && r.style.transform && img.matches(r.selectorText)){
        out.push({sel:r.selectorText,tf:r.style.transform,href:sheet.href});
      }
    }
  }
  return out;
})()
